INSERT INTO standing_adjustments (table_id, club_id, points, goals_for, goals_against, played, won, drawn, lost, reason) SELECT (SELECT id FROM standing_tables WHERE legacy_id = 322447), (SELECT club_id FROM club_legacy_ids WHERE legacy_id = 273321), 3, 5, 35, 12, 0, 3, 9, 'Tabla final importada de AnWP' WHERE (SELECT club_id FROM club_legacy_ids WHERE legacy_id = 273321) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM standing_adjustments WHERE table_id = (SELECT id FROM standing_tables WHERE legacy_id = 322447) AND club_id = (SELECT club_id FROM club_legacy_ids WHERE legacy_id = 273321));
